def choose_move(observation):
    dx = 0
    dy = 0

    wx = observation.get("self_position", {}).get("x", 0)
    wy = observation.get("self_position", {}).get("y", 0)

    ox = observation.get("opponent_position", {}).get("x", 0)
    oy = observation.get("opponent_position", {}).get("y", 0)

    # Simple heuristic: move away from opponent, prefer staying if blocked
    if wx < ox:
        dx = -1
    elif wx > ox:
        dx = 1
    else:
        dx = 0

    if wy < oy:
        dy = -1
    elif wy > oy:
        dy = 1
    else:
        dy = 0

    # Clamp to -1,0,1 (already ensured)
    if dx not in (-1, 0, 1) or dy not in (-1, 0, 1):
        dx = 0
        dy = 0

    return [dx, dy]
